package com.campusradar.interview;

import com.campusradar.common.ApiProblem;
import com.campusradar.growth.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static com.campusradar.growth.PersonalStore.map;

@Service
public class InterviewService {
    private final PersonalStore store;
    public InterviewService(PersonalStore store){this.store=store;}
    private static final List<String> SHARED=List.of("title","startsAt","endsAt","timezone","location","meetingUrl","status");
    public List<Map<String,Object>> rounds(String u,String app){store.one("applications",u,app);return store.query("SELECT * FROM interview_rounds WHERE user_id=:u AND application_id=:app ORDER BY sequence,id",map("u",u,"app",app));}
    public Map<String,Object> roundCreate(String u,String app,Map<String,Object>b){store.one("applications",u,app);PersonalStore.timeRange(b,true);sequence(u,app,null,b.get("sequence"));var full=new LinkedHashMap<>(b);full.put("applicationId",app);var row=store.insert("interview_rounds",u,full);syncEvent(u,row);return row;}
    public Map<String,Object> roundPatch(String u,String id,Map<String,Object>b){var old=store.one("interview_rounds",u,id);var full=new LinkedHashMap<>(old);full.putAll(b);PersonalStore.timeRange(full,true);sequence(u,old.get("applicationId").toString(),id,full.get("sequence"));var row=store.patch("interview_rounds",u,id,b);syncEvent(u,row);return row;}
    private void syncEvent(String u,Map<String,Object>round){var rows=store.query("SELECT * FROM calendar_events WHERE user_id=:u AND round_id=:round",map("u",u,"round",round.get("id")));if(round.get("startsAt")==null){if(!rows.isEmpty())store.delete("calendar_events",u,rows.getFirst().get("id").toString(),((Number)rows.getFirst().get("version")).intValue());return;}var event=new LinkedHashMap<String,Object>();for(String k:SHARED)event.put(k,round.get(k));event.put("kind","ASSESSMENT".equals(round.get("roundType"))?"ASSESSMENT":"INTERVIEW");event.put("applicationId",round.get("applicationId"));event.put("roundId",round.get("id"));if(rows.isEmpty()){event.put("notes","");store.insert("calendar_events",u,event);}else{event.put("version",rows.getFirst().get("version"));store.patch("calendar_events",u,rows.getFirst().get("id").toString(),event);}}
    public void roundDelete(String u,String id,int version){PersonalStore.version(store.one("interview_rounds",u,id),version);var p=map("u",u,"id",id);var recordings=store.db.queryForList("SELECT recording_file_id FROM interview_reviews WHERE user_id=:u AND round_id=:id AND recording_file_id IS NOT NULL",p,String.class);store.db.update("DELETE FROM interview_reviews WHERE user_id=:u AND round_id=:id",p);store.db.update("DELETE FROM calendar_events WHERE user_id=:u AND round_id=:id",p);store.delete("interview_rounds",u,id,version);recordings.forEach(file->eraseDetachedRecording(u,file));}
    private Map<String,Object> linkedRound(String u,Map<String,Object>e){if(e.get("applicationId")!=null)store.one("applications",u,e.get("applicationId").toString());if(e.get("roundId")==null)return null;var round=store.one("interview_rounds",u,e.get("roundId").toString());if(!Objects.equals(round.get("applicationId"),e.get("applicationId")))throw new ApiProblem(422,"RELATION_MISMATCH","轮次与投递关联不一致。");String kind="ASSESSMENT".equals(round.get("roundType"))?"ASSESSMENT":"INTERVIEW";if(!kind.equals(e.get("kind")))throw new ApiProblem(422,"RELATION_MISMATCH","轮次日程类型与面试类型不一致。");return round;}
    private void syncRound(String u,Map<String,Object>event,Map<String,Object>round){if(round==null)return;var b=new LinkedHashMap<String,Object>();for(String k:SHARED)b.put(k,event.get(k));b.put("version",round.get("version"));store.patch("interview_rounds",u,round.get("id").toString(),b);}
    public Map<String,Object> eventCreate(String u,Map<String,Object>b){PersonalStore.timeRange(b,false);var round=linkedRound(u,b);if(round!=null&&!store.query("SELECT id FROM calendar_events WHERE user_id=:u AND round_id=:round",map("u",u,"round",round.get("id"))).isEmpty())throw new ApiProblem(409,"ROUND_ALREADY_SCHEDULED","此轮次已有关联日程，请编辑已有日程。");syncRound(u,b,round);return decorate(u,store.insert("calendar_events",u,b));}
    private void unschedule(String u,String round){if(round==null)return;var row=store.one("interview_rounds",u,round);store.patch("interview_rounds",u,round,map("version",row.get("version"),"startsAt",null,"endsAt",null));}
    public Map<String,Object> eventPatch(String u,String id,Map<String,Object>b){var old=store.one("calendar_events",u,id);PersonalStore.version(old,b.get("version"));var full=new LinkedHashMap<>(old);full.putAll(b);PersonalStore.timeRange(full,false);var round=linkedRound(u,full);if(round!=null&&!store.query("SELECT id FROM calendar_events WHERE user_id=:u AND round_id=:round AND id<>:id",map("u",u,"round",round.get("id"),"id",id)).isEmpty())throw new ApiProblem(409,"ROUND_ALREADY_SCHEDULED","此轮次已有日程，请编辑已有日程。");if(!Objects.equals(old.get("roundId"),full.get("roundId")))unschedule(u,(String)old.get("roundId"));syncRound(u,full,round);return decorate(u,store.patch("calendar_events",u,id,b));}
    public void eventDelete(String u,String id,int version){var old=store.one("calendar_events",u,id);PersonalStore.version(old,version);unschedule(u,(String)old.get("roundId"));store.delete("calendar_events",u,id,version);}
    public Map<String,Object> decorate(String u,Map<String,Object>e){var ids=store.db.queryForList("SELECT id FROM calendar_events WHERE user_id=:u AND id<>:id AND status='SCHEDULED' AND starts_at<:end AND ends_at>:start ORDER BY starts_at,id LIMIT 100",map("u",u,"id",e.get("id"),"start",java.sql.Timestamp.from(java.time.Instant.parse(e.get("startsAt").toString())),"end",java.sql.Timestamp.from(java.time.Instant.parse(e.get("endsAt").toString()))),String.class);e.put("conflictIds","SCHEDULED".equals(e.get("status"))?ids:List.of());return e;}
    public Map<String,Object> review(String u,String round){store.one("interview_rounds",u,round);var rows=store.query("SELECT * FROM interview_reviews WHERE user_id=:u AND round_id=:round",map("u",u,"round",round));if(rows.isEmpty())throw PersonalStore.missing();return rows.getFirst();}
    public Map<String,Object> reviewPut(String u,String round,Map<String,Object>b){store.one("interview_rounds",u,round);if(b.get("recordingFileId")!=null){var rows=store.db.queryForList("SELECT id FROM files WHERE user_id=:u AND id=:id AND purpose='RECORDING' AND state='READY'",map("u",u,"id",b.get("recordingFileId")));if(rows.isEmpty())throw PersonalStore.missing();}var rows=store.query("SELECT * FROM interview_reviews WHERE user_id=:u AND round_id=:round",map("u",u,"round",round));if(rows.isEmpty()){if(((Number)b.get("version")).intValue()!=0)throw new ApiProblem(409,"VERSION_CONFLICT","首次保存复盘版本须为0。");var full=new LinkedHashMap<>(b);full.put("roundId",round);return store.insert("interview_reviews",u,full);}var old=rows.getFirst();var saved=store.patch("interview_reviews",u,old.get("id").toString(),b);if(!Objects.equals(old.get("recordingFileId"),saved.get("recordingFileId")))eraseDetachedRecording(u,(String)old.get("recordingFileId"));return saved;}
    private void sequence(String user,String app,String id,Object sequence){if(store.db.queryForObject("SELECT COUNT(*) FROM interview_rounds WHERE user_id=:u AND application_id=:app AND sequence=:sequence AND (:id IS NULL OR id<>:id)",map("u",user,"app",app,"id",id,"sequence",sequence),Integer.class)>0)throw new ApiProblem(409,"ROUND_SEQUENCE_EXISTS","此投递已有相同序号的面试轮次。");}
    private void eraseDetachedRecording(String user,String file){if(file==null)return;store.db.update("UPDATE files SET state='PENDING_DELETE',version=version+1,updated_at=CURRENT_TIMESTAMP WHERE id=:id AND user_id=:u AND purpose='RECORDING' AND state='READY' AND NOT EXISTS(SELECT 1 FROM interview_reviews r WHERE r.user_id=:u AND r.recording_file_id=:id)",map("u",user,"id",file));}
}
